import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.CT6jiXWi.js";const g=JSON.parse('{"title":"Terminology: Federation, Delegation, Replication & Caching","description":"","frontmatter":{},"headers":[],"relativePath":"federation/concepts/terminology.md","filePath":"federation/concepts/terminology.md","lastUpdated":1783589060000}'),n={name:"federation/concepts/terminology.md"};function r(s,e,d,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="terminology-federation-delegation-replication-caching" tabindex="-1">Terminology: Federation, Delegation, Replication &amp; Caching <a class="header-anchor" href="#terminology-federation-delegation-replication-caching" aria-label="Permalink to &quot;Terminology: Federation, Delegation, Replication &amp; Caching&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Shared glossary</p><p>The base vocabulary (pipeline, source/target, mode, delta, federation, delegation, replication, consumption view, caching) is defined once in the <a href="/cds-data/concepts/terminology.html">shared Terminology</a>. This page adds the <strong>federation-specific</strong> depth: the industry and CAP alignment, the Calesi pattern, and the naming rationale.</p></div><p>This document defines the key terms used by <code>cds-data-pipeline</code> and <code>cds-data-federation</code>, explains how they relate to SAP CAP&#39;s official definitions and to the broader industry, and provides the rationale for our naming choices.</p><hr><h2 id="what-federation-means-in-this-plugin" tabindex="-1">What &quot;federation&quot; means in this plugin <a class="header-anchor" href="#what-federation-means-in-this-plugin" aria-label="Permalink to &quot;What &quot;federation&quot; means in this plugin&quot;">​</a></h2><p><strong>Federation means: integrating remote service models into the consumer&#39;s data model and providing strategies for how that remote data is accessed at runtime.</strong></p><p>The developer declares two things:</p><ol><li><strong>What</strong> to federate — a CDS consumption view (<code>entity X as projection on remote.Y</code>) that defines the schema contract: which remote fields, what shape, what renames.</li><li><strong>How</strong> to access it — a <code>@federation.*</code> annotation that selects the runtime strategy: delegate (live), replicate (scheduled sync), optionally with caching.</li></ol><p>From the developer&#39;s perspective, the intent is always the same: &quot;I need this remote entity&#39;s data available in my application.&quot; Whether that data is fetched live or replicated locally is a runtime concern, not a modeling concern.</p><h3 id="pipeline-replication-materialization-movement-—-four-distinct-ideas" tabindex="-1">Pipeline, replication, materialization, movement — four distinct ideas <a class="header-anchor" href="#pipeline-replication-materialization-movement-—-four-distinct-ideas" aria-label="Permalink to &quot;Pipeline, replication, materialization, movement — four distinct ideas&quot;">​</a></h3><p>The engine package (<a href="https://www.npmjs.com/package/cds-data-pipeline" target="_blank" rel="noreferrer"><code>cds-data-pipeline</code></a>) talks about <strong>pipelines</strong>, not replications; replication is one specific <em>shape</em> of pipeline. The engine <strong>derives</strong> each pipeline&#39;s <code>kind</code> from the configuration shape — consumers do not pass <code>kind</code> to <code>addPipeline</code>. The four terms are deliberately narrow:</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th><th>Status</th></tr></thead><tbody><tr><td><strong>Pipeline</strong></td><td>A linear <code>READ → MAP → WRITE</code> job between exactly one source and one target, with built-in tracker, retry, concurrency guard, and event hooks. This is what <code>cds-data-pipeline</code> provides. Every pipeline carries a <em>derived</em> <code>kind</code>, inferred at registration time.</td><td>Engine primitive.</td></tr><tr><td><strong>Replication</strong> (derived <code>kind: &#39;replicate&#39;</code>)</td><td>Entity-shape read + row-preserving UPSERT: <code>source.entity</code> (or <code>rest.path</code> for REST) to a db target. One source row produces one target row on the key.</td><td>Implemented in v1.0.</td></tr><tr><td><strong>Materialization</strong> (derived <code>kind: &#39;materialize&#39;</code>)</td><td>Query-shape read + snapshot write: target is rebuilt from a user-supplied CQN <code>source.query</code> (projections, joins, <code>GROUP BY</code>, computed columns). Writes are <code>full</code> or <code>partial-refresh</code>.</td><td>Planned in v1.0 (validation-only).</td></tr><tr><td><strong>Movement</strong> (derived <code>kind: &#39;move&#39;</code>)</td><td>Entity-shape read forwarded to a non-database target (message bus, object store, external HTTP endpoint) — <code>target.service</code> is anything other than <code>&#39;db&#39;</code>.</td><td>Planned in v1.0 (validation-only).</td></tr></tbody></table><p>See the engine site&#39;s <a href="/cds-data/pipeline/guide/concepts/inference.html">inference rules</a> page for the full derivation table and registration-time validation matrix.</p><h3 id="federation-pipelines-and-replication-sit-at-different-layers" tabindex="-1">Federation, pipelines, and replication sit at different layers <a class="header-anchor" href="#federation-pipelines-and-replication-sit-at-different-layers" aria-label="Permalink to &quot;Federation, pipelines, and replication sit at different layers&quot;">​</a></h3><p><strong>Federation</strong> is the declarative, remote-service integration layer: consumption views, <code>@federation.*</code> annotations, cross-service <code>$expand</code> and navigation, CUD forwarding. <strong>The pipeline engine</strong> is the underlying scheduled job runtime — source adapters, delta tracking, retry, the <code>Pipelines</code> / <code>PipelineRuns</code> tracker, and the management service.</p><p>The federation plugin (<code>cds-data-federation</code>) composes the pipeline engine (<code>cds-data-pipeline</code>) to implement <code>@federation.replicate</code> — each annotated entity becomes one entity-shape <code>addPipeline({ ... })</code> call via <code>packages/cds-data-federation/srv/pipeline-binding.js</code>, and the engine derives <code>kind: &#39;replicate&#39;</code> from the config. The engine does not depend on federation and can be used standalone — either programmatically via <code>cds.connect.to(&#39;DataPipelineService&#39;).addPipeline({ ... })</code> or from any other plugin layered on top of it.</p><hr><h2 id="industry-context" tabindex="-1">Industry context <a class="header-anchor" href="#industry-context" aria-label="Permalink to &quot;Industry context&quot;">​</a></h2><p>The broader data industry defines data federation as follows:</p><blockquote><p>&quot;Data Federation is a data management technique that <strong>makes multiple data sources appear as a single one</strong>.&quot; — Denodo (data virtualization vendor)</p></blockquote><blockquote><p>&quot;Data federation creates a <strong>virtual, unified view of disparate data sources</strong> without moving data. Instead of copying data into a centralized repository, the federation layer sits on top of your existing systems and queries them directly.&quot; — Fivetran</p></blockquote><p>Key characteristics of data federation in the industry:</p><ul><li><strong>Unified access</strong> — multiple heterogeneous sources queried through a single interface</li><li><strong>Transparency</strong> — the consumer does not need to know where data physically resides</li><li><strong>Strategy-agnostic</strong> — implementations range from live virtual queries to materialized views to full replication; the term covers all of them</li><li><strong>Middleware-driven</strong> — a federation layer handles query translation, schema mapping, and result assembly</li></ul><p>Our plugin follows this definition: the CDS consumption view is the unified interface, the plugin is the middleware layer, and delegate/replicate are the implementation strategies.</p><hr><h2 id="calesi-—-cap-level-service-interfaces" tabindex="-1">&#39;Calesi&#39; — CAP-level Service Interfaces <a class="header-anchor" href="#calesi-—-cap-level-service-interfaces" aria-label="Permalink to &quot;&#39;Calesi&#39; — CAP-level Service Interfaces&quot;">​</a></h2><blockquote><p>&#39;Calesi&#39; stands for CAP-level Service Interfaces, and refers to the increasing numbers of BTP platform services which offer a CAP-level client library. — <a href="https://cap.cloud.sap/docs/get-started/concepts#the-calesi-pattern" target="_blank" rel="noreferrer">Core Concepts › The Calesi Pattern</a></p></blockquote><blockquote><p>Essentially, the &#39;Calesi&#39; pattern is about encapsulating any external communication within a CAP-service-based interface, so that the actual consumption and/or implementation benefits from the related advantages, such as agnostic consumption, intrinsic extensibility, automatic mocking, and so on. — <a href="https://cap.cloud.sap/docs/get-started/concepts#the-calesi-pattern" target="_blank" rel="noreferrer">Core Concepts › The Calesi Pattern</a></p></blockquote><p>SAP provides first-party Calesi plugins for platform services (Attachments, Audit Log, Notifications, Telemetry, ...). The <a href="https://cap.cloud.sap/docs/guides/integration/calesi" target="_blank" rel="noreferrer">CAP-Level Service Integration guide</a> applies the same pattern to <strong>remote data services</strong> — the problem space this plugin targets.</p><p><strong><code>cds-data-federation</code> is a Calesi plugin for remote data services.</strong> It encapsulates outbound OData/REST calls behind a CAP service interface, exposes two strategies (<code>@federation.delegate</code> and <code>@federation.replicate</code>), and benefits from the pattern&#39;s guarantees: agnostic consumption (<code>cds.connect.to</code>), intrinsic extensibility (before/on/after event handlers), and automatic mocking (CAP mocks the remote out of the box).</p><hr><h2 id="cap-s-definitions-service-integration-guide" tabindex="-1">CAP&#39;s definitions (Service Integration guide) <a class="header-anchor" href="#cap-s-definitions-service-integration-guide" aria-label="Permalink to &quot;CAP&#39;s definitions (Service Integration guide)&quot;">​</a></h2><p>SAP&#39;s <a href="https://cap.cloud.sap/docs/guides/integration/calesi" target="_blank" rel="noreferrer">Service Integration guide</a> applies the Calesi pattern to remote data services and defines these terms as <strong>peer concepts</strong> under the umbrella of &quot;Integration Logic&quot;:</p><h3 id="integration" tabindex="-1">Integration <a class="header-anchor" href="#integration" aria-label="Permalink to &quot;Integration&quot;">​</a></h3><p>The top-level umbrella. The Service Integration guide covers the full lifecycle of working with remote services: importing APIs, creating consumption views, writing integration logic, events, and messaging.</p><h3 id="data-federation" tabindex="-1">Data Federation <a class="header-anchor" href="#data-federation" aria-label="Permalink to &quot;Data Federation&quot;">​</a></h3><p>CAP has a dedicated guide: <a href="https://cap.cloud.sap/docs/guides/integration/data-federation" target="_blank" rel="noreferrer">CAP-level Data Federation</a>. The meaning is specific:</p><blockquote><p>&quot;Relying on live calls to remote services per row is clearly not an option. Instead, we&#39;d rather ensure that data required in close access is really available locally, so it can be joined with own data using SQL JOINs. <strong>This is what data federation is all about.</strong>&quot;</p></blockquote><p>CAP&#39;s <code>@federated</code> annotation marks entities for <strong>local replication</strong> so their data is &quot;in close access.&quot; The implementation pattern: <code>@cds.persistence.table</code> + UPSERT-based replication.</p><h3 id="delegation" tabindex="-1">Delegation <a class="header-anchor" href="#delegation" aria-label="Permalink to &quot;Delegation&quot;">​</a></h3><blockquote><p>&quot;Even with data federation in place, there are still several scenarios where we need to reach out to remote services on demand. Value helps are a prime example.&quot;</p></blockquote><p>Implementation: <code>this.on(&#39;READ&#39;, Customers, req =&gt; s4.run(req.query))</code> — forwarding a query live to a remote service. CAP emphasizes &quot;Automatic Query Translation&quot; as the key capability: field names are translated through the CDS projection chain.</p><h3 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h3><blockquote><p>&quot;The term &#39;navigation&#39; commonly refers to <strong>traversing associations between entities</strong> in queries. In CAP, this is typically expressed using <strong>path expressions along (chains of) associations</strong> — e.g., <code>flight.origin.name</code> — which can show up in all query clauses (select, from, where, order by, and group by).&quot;</p></blockquote><p>When navigation paths cross service boundaries, queries must be split manually.</p><h3 id="expands" tabindex="-1">Expands <a class="header-anchor" href="#expands" aria-label="Permalink to &quot;Expands&quot;">​</a></h3><p><code>$expand</code> across service boundaries. See <a href="./cross-service-scenarios.html">Cross-Service Scenarios</a> for the canonical reference. Four topologies:</p><ul><li><strong>Delegated expand</strong> (formerly Scenario A): both entities on the same remote — CAP handles natively</li><li><strong>Cross-service expand: local → remote</strong> (formerly Scenario B): local entity expands to remote — plugin adds batch-fetch + stitch</li><li><strong>Cross-service expand: remote → local</strong> (formerly Scenario C): remote entity expands to local — plugin adds reverse fetch against local DB</li><li><strong>Cross-service expand: cross-provider</strong>: local entity expands to targets on <em>different</em> remote providers — plugin issues one batch-fetch per provider</li></ul><p>In all four cases the remote side is <code>@federation.delegate</code>. <code>@federation.replicate</code> entities participate only as the local side — after replication they are ordinary local tables, indistinguishable from plain local entities at query time. There are no <code>@federation.replicate</code>-only scenarios.</p><h3 id="caching" tabindex="-1">Caching <a class="header-anchor" href="#caching" aria-label="Permalink to &quot;Caching&quot;">​</a></h3><p>CAP has <strong>no native caching</strong> for remote service responses or replicated data. No TTL, no LRU, no cache invalidation. Every remote call hits the network unless you add caching yourself.</p><hr><h2 id="how-our-terms-map-to-cap-s-terms" tabindex="-1">How our terms map to CAP&#39;s terms <a class="header-anchor" href="#how-our-terms-map-to-cap-s-terms" aria-label="Permalink to &quot;How our terms map to CAP&#39;s terms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>CAP (Service Integration guide) definition</th><th>Our plugin&#39;s definition</th><th>Alignment</th></tr></thead><tbody><tr><td><strong>Integration</strong></td><td>Umbrella for all remote service work (APIs, events, messaging)</td><td>Not used as primary term; plugin sits under integration</td><td>No conflict</td></tr><tr><td><strong>Federation</strong></td><td>Narrow: replication for local &quot;close access&quot; (SQL joins)</td><td>Broad: integrating remote models + all access strategies</td><td>Intentionally broader</td></tr><tr><td><strong>Delegation</strong></td><td>Live forwarding: <code>req =&gt; remote.run(req.query)</code></td><td><code>@federation.delegate</code> — same behavior</td><td>Aligned</td></tr><tr><td><strong>Navigation</strong></td><td>Path expressions traversing associations in queries</td><td><code>translateNavigationFilters()</code> — same concept</td><td>Aligned</td></tr><tr><td><strong>Replication</strong></td><td>Mechanism: copy remote data to local DB via UPSERT</td><td><code>@federation.replicate</code> — same mechanism</td><td>Aligned</td></tr><tr><td><strong>Expand</strong></td><td><code>$expand</code> across service boundaries</td><td>See <a href="./cross-service-scenarios.html">Cross-Service Scenarios</a> — delegated expand uses <code>@federation.delegate</code> on both sides; cross-service expand (local → remote / remote → local / cross-provider) uses <code>@federation.delegate</code> on the remote side with any local entity (including <code>@federation.replicate</code>) on the other</td><td>Aligned</td></tr><tr><td><strong>Caching</strong></td><td>No CAP-native concept exists</td><td>Cross-cutting option: <code>cache.strategy: &#39;response&#39;</code> via <code>cds-caching</code>, or <code>cache.strategy: &#39;entity&#39;</code> (SQLite + pipeline)</td><td>No conflict</td></tr></tbody></table><h3 id="annotation-federated-cap-sample-vs-federation-this-plugin" tabindex="-1">Annotation: <code>@federated</code> (CAP sample) vs <code>@federation.*</code> (this plugin) <a class="header-anchor" href="#annotation-federated-cap-sample-vs-federation-this-plugin" aria-label="Permalink to &quot;Annotation: `@federated` (CAP sample) vs `@federation.*` (this plugin)&quot;">​</a></h3><p>CAP&#39;s <a href="https://cap.cloud.sap/docs/guides/integration/data-federation" target="_blank" rel="noreferrer">Data Federation guide</a> and the <a href="https://github.com/capire/xtravels/blob/main/srv/data-federation.js" target="_blank" rel="noreferrer">xtravels sample</a> introduce a <code>@federated</code> annotation (no dot, no strategy) used purely as a marker. A ~20-line <code>data-federation.js</code> in the sample walks the CSN, marks <code>@federated</code> entities as persistence tables, and implements a naive <code>modifiedAt</code>-based polling replication:</p><div class="language-cds vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">cds</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@federated entity Customers </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">as</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> projection</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> on</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> S4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">A_BusinessPartner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> };</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This is conceptually similar to — but intentionally much smaller than — our <code>@federation.*</code> namespace.</p><table tabindex="0"><thead><tr><th>Aspect</th><th>CAP <code>@federated</code> (sample)</th><th><code>@federation.*</code> (this plugin)</th></tr></thead><tbody><tr><td>Namespace</td><td>Top-level annotation (adjective)</td><td>Dotted namespace (<code>delegate</code> / <code>replicate</code> as strategy suffixes)</td></tr><tr><td>Ownership</td><td>CAP sample code (not a runtime built-in)</td><td>This plugin</td></tr><tr><td>Strategy</td><td>Implicit: replication only</td><td>Explicit: <code>delegate</code> or <code>replicate</code> at the annotation site</td></tr><tr><td>Options</td><td>None</td><td><code>cache</code>, <code>writable</code> / <code>create</code> / <code>update</code> / <code>delete</code>, <code>schedule</code>, <code>mode</code>, <code>batchSize</code>, <code>source</code></td></tr><tr><td>Delta modes</td><td><code>modifiedAt</code>-only polling</td><td><code>timestamp</code> / <code>key</code> / <code>datetime-fields</code> via adapter</td></tr><tr><td>Adapters</td><td>OData / HCQL (CAP-native)</td><td>OData v2/v4, REST (with pagination + delta URL param), pluggable BaseAdapter</td></tr><tr><td>Resilience</td><td>None</td><td><code>withRetry()</code> with exponential backoff + skip-4xx, concurrency guard via optimistic UPDATE</td></tr><tr><td>Hooks</td><td>None</td><td>`before/on/after(&#39;PIPELINE.READ&#39;</td></tr><tr><td>Observability</td><td>None</td><td><code>Pipelines</code>, <code>PipelineRuns</code> entities + management OData service</td></tr><tr><td>View mapping</td><td>Verbatim replication</td><td>Scanner extracts <code>localToRemote</code>/<code>remoteToLocal</code>; MAP phase renames fields</td></tr><tr><td>Delegation</td><td>Not covered</td><td><code>@federation.delegate</code> with cross-service <code>$expand</code> (see <a href="./cross-service-scenarios.html">Cross-Service Scenarios</a>), cross-service navigation, static where, CUD forwarding</td></tr></tbody></table><p>There is <strong>no technical collision</strong>: <code>@federated</code> and <code>@federation.delegate</code> / <code>@federation.replicate</code> are distinct identifiers in distinct namespaces. Annotation names stay compatible if a project uses both (e.g. during migration). If CAP promotes <code>@federated</code> from sample code to a runtime built-in, we will reassess alignment at that point — possibly by recognising <code>@federated</code> on a consumption view as a synonym for <code>@federation.replicate</code> with defaults.</p><hr><h2 id="why-federation-as-umbrella-not-integration" tabindex="-1">Why &quot;federation&quot; as umbrella (not &quot;integration&quot;) <a class="header-anchor" href="#why-federation-as-umbrella-not-integration" aria-label="Permalink to &quot;Why &quot;federation&quot; as umbrella (not &quot;integration&quot;)&quot;">​</a></h2><p>We considered two naming options:</p><h3 id="option-a-cds-data-federation-with-federation-chosen" tabindex="-1">Option A: <code>cds-data-federation</code> with <code>@federation.*</code> (chosen) <a class="header-anchor" href="#option-a-cds-data-federation-with-federation-chosen" aria-label="Permalink to &quot;Option A: `cds-data-federation` with `@federation.*` (chosen)&quot;">​</a></h3><ul><li>Follows the <strong>industry convention</strong> where &quot;data federation&quot; = unified access across heterogeneous sources, regardless of strategy</li><li>CAP&#39;s own <code>@federated</code> annotation is close in spirit — the xtravels sample treats it as &quot;this data should be transparently available regardless of where it lives&quot;</li><li><code>@federation.delegate</code> and <code>@federation.replicate</code> read naturally: &quot;this entity participates in data federation, using strategy X&quot;</li><li>The namespace <code>@federation.*</code> is cleanly separated from CAP&#39;s <code>@federated</code> (namespace vs. adjective)</li><li>The package name <code>cds-data-federation</code> communicates scope clearly</li></ul><h3 id="option-b-cds-data-integration-with-integration-rejected" tabindex="-1">Option B: <code>cds-data-integration</code> with <code>@integration.*</code> (rejected) <a class="header-anchor" href="#option-b-cds-data-integration-with-integration-rejected" aria-label="Permalink to &quot;Option B: `cds-data-integration` with `@integration.*` (rejected)&quot;">​</a></h3><ul><li>Would align with CAP&#39;s top-level umbrella term</li><li>But &quot;integration&quot; is too broad — it covers events, messaging, outbox, etc.</li><li>The plugin focuses specifically on <strong>data access patterns</strong> (read delegation + replication), not the full integration spectrum</li><li>Risk of colliding with future CAP-owned <code>@integration.*</code> annotations</li></ul><h3 id="the-intentional-divergence" tabindex="-1">The intentional divergence <a class="header-anchor" href="#the-intentional-divergence" aria-label="Permalink to &quot;The intentional divergence&quot;">​</a></h3><p>In the Service Integration guide, &quot;Data Federation&quot; and &quot;Delegation&quot; are <strong>sibling sections</strong> under &quot;Integration Logic.&quot; Our plugin makes delegation a <strong>strategy within</strong> federation. This is intentional:</p><ul><li>From the developer&#39;s perspective, the decision is: &quot;I have a remote entity in my model. How should I access its data?&quot; The answer is <code>@federation.delegate</code> or <code>@federation.replicate</code>.</li><li>Separating them into different annotation namespaces would force the developer to think about conceptual categories instead of practical choices.</li><li>The consumption view is the constant; the strategy is the variable.</li></ul><hr><h2 id="annotation-design" tabindex="-1">Annotation design <a class="header-anchor" href="#annotation-design" aria-label="Permalink to &quot;Annotation design&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@federation.delegate                              — live proxy (industry &quot;federation&quot;)</span></span>\n<span class="line"><span>@federation.delegate: { cache: { ttl: 60000 } }  — live proxy + response caching</span></span>\n<span class="line"><span>@federation.replicate                             — scheduled sync (CAP &quot;data federation&quot;)</span></span>\n<span class="line"><span>@federation.replicate: { schedule: &#39;*/10 * * * *&#39;, cache: { ttl: 300000 } }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Design principles:</p><ul><li><strong>Strategy is the annotation name</strong>, not an option — <code>@federation.delegate</code> vs <code>@federation.replicate</code>. Easy to scan visually in CDS models.</li><li><strong>Caching is an option</strong>, not a strategy — it can be applied to either strategy. Caching is orthogonal to how data is accessed.</li><li><strong>No <code>@cds.federated</code></strong> — that namespace belongs to SAP. We use <code>@federation.*</code> to stay in our own namespace.</li></ul><hr><h2 id="summary-for-presentation" tabindex="-1">Summary for presentation <a class="header-anchor" href="#summary-for-presentation" aria-label="Permalink to &quot;Summary for presentation&quot;">​</a></h2><p><strong>One-liner:</strong> Federation = integrating remote models into your data model + choosing how to access them.</p><p><strong>Three-part model:</strong></p><table tabindex="0"><thead><tr><th></th><th>What</th><th>How</th><th>Annotation</th></tr></thead><tbody><tr><td><strong>Schema</strong></td><td>Consumption view defines fields, shape, renames</td><td>CDS projection: <code>entity X as projection on remote.Y { ... }</code></td><td>(modeling, no annotation needed)</td></tr><tr><td><strong>Strategy</strong></td><td>Live proxy or local sync</td><td><code>delegate</code> = forward query; <code>replicate</code> = scheduled UPSERT</td><td><code>@federation.delegate</code> / <code>@federation.replicate</code></td></tr><tr><td><strong>Caching</strong></td><td>Optional read accelerator</td><td><strong><code>response</code></strong>: TTL cache keyed by query signature (<code>cds-caching</code>). <strong><code>entity</code></strong>: full-entity SQLite snapshot refreshed on TTL miss (<code>cds-data-pipeline</code>). Orthogonal to delegate vs replicate.</td><td><code>{ cache: { ttl, strategy } }</code></td></tr></tbody></table><p><strong>Relationship to CAP terminology:</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CAP &quot;Integration&quot; (umbrella)</span></span>\n<span class="line"><span> ├── Data Federation (replication for close access)  ─┐</span></span>\n<span class="line"><span> ├── Delegation (live forwarding)                     ├── Our @federation.* (unified)</span></span>\n<span class="line"><span> ├── Navigation (association path traversal)          │   delegate = CAP delegation</span></span>\n<span class="line"><span> ├── Expands ($expand across services)                │   replicate = CAP data federation</span></span>\n<span class="line"><span> └── Outboxed Emits (async events)                   ─┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><strong>Why this naming works:</strong></p><ol><li>Matches the industry definition of data federation (Denodo, Fivetran, Oracle)</li><li>Developer-centric: one annotation namespace, strategy as the only choice</li><li>Internal terms (delegate, replicate, navigation, expand) all align with CAP</li><li>Clean separation from CAP&#39;s <code>@federated</code> and <code>@cds.*</code> namespaces</li></ol><hr><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>Service Integration guide (CAP-Level Service Integration)</td><td><a href="https://cap.cloud.sap/docs/guides/integration/calesi" target="_blank" rel="noreferrer">https://cap.cloud.sap/docs/guides/integration/calesi</a></td></tr><tr><td>The Calesi Pattern (CAP-level Service Interfaces)</td><td><a href="https://cap.cloud.sap/docs/get-started/concepts#the-calesi-pattern" target="_blank" rel="noreferrer">https://cap.cloud.sap/docs/get-started/concepts#the-calesi-pattern</a></td></tr><tr><td>CAP-level Data Federation</td><td><a href="https://cap.cloud.sap/docs/guides/integration/data-federation" target="_blank" rel="noreferrer">https://cap.cloud.sap/docs/guides/integration/data-federation</a></td></tr><tr><td>Denodo: Data Federation Definition</td><td><a href="https://www.denodo.com/en/glossary/data-federation-definition-importance-best-practices" target="_blank" rel="noreferrer">https://www.denodo.com/en/glossary/data-federation-definition-importance-best-practices</a></td></tr><tr><td>Fivetran: What is Data Federation?</td><td><a href="https://www.fivetran.com/learn/data-federation" target="_blank" rel="noreferrer">https://www.fivetran.com/learn/data-federation</a></td></tr><tr><td>xtravels sample (data-federation.js)</td><td><a href="https://github.com/capire/xtravels/blob/main/srv/data-federation.js" target="_blank" rel="noreferrer">https://github.com/capire/xtravels/blob/main/srv/data-federation.js</a></td></tr></tbody></table>',87)])])}const u=t(n,[["render",r]]);export{g as __pageData,u as default};
